//! Desktop-managed state units only; Chromium profiles and caches are excluded.
use super::*;
#[derive(Clone,Serialize,Deserialize,PartialEq,Eq)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Unit{pub name:String,pub kind:String,pub present:bool}
/// 旧备份未声明的新偏好单元也进入交换计划；恢复前数据留在同一安全副本中。
pub fn restore_units(source:&[Unit])->Result<Vec<Unit>>{validate_units(source)?;let mut result=source.to_vec();for(name,kind)in UNITS{if !source.iter().any(|unit|unit.name==*name){result.push(Unit{name:name.to_string(),kind:kind.to_string(),present:false})}}Ok(result)}
pub const UNITS:&[(&str,&str)]=&[("appearance.json","file"),("general-preferences.json","file"),("window-close.json","file"),("current-user-profile.json","file"),("onboarding.json","file"),("restorable-location.json","file"),("navigation.json","file"),("window-state.json","file"),("pet-window-state.json","file"),("browser-profiles.json","file"),("browser-preferences.json","file"),("browser-downloads.json","file"),("local-composer-attachments-v1.json","file"),("private-input-recovery-v1","directory"),("execution-web.json","file"),("interaction-computer-preferences.json","file"),("interaction-results-v1","directory"),("keyboard-shortcuts-v1.json","file"),("workbench-editor-recovery-v1","directory"),("logging.json","file")];
pub fn units(root:&Path)->Result<Vec<Unit>>{UNITS.iter().map(|(name,kind)|{let path=root.join(name);let present=path.exists();if present{no_link(&path)?;ensure!(if *kind=="file"{path.is_file()}else{path.is_dir()},"backup.desktop_unit_kind_changed");}Ok(Unit{name:name.to_string(),kind:kind.to_string(),present})}).collect()}
pub fn files_for(root:&Path)->Result<Vec<(String,PathBuf)>>{let mut result=Vec::new();for unit in units(root)?{if !unit.present{continue}let path=root.join(&unit.name);if unit.kind=="file"{result.push((unit.name,path))}else{result.extend(files(&path)?.into_iter().map(|(name,path)|(format!("{}/{name}",unit.name),path)));}}result.sort_by(|a,b|a.0.cmp(&b.0));Ok(result)}
pub fn validate_units(units:&[Unit])->Result<()>{ensure!(units.len()<=UNITS.len(),"backup.invalid_desktop_units");let mut seen=HashSet::new();for unit in units{ensure!(UNITS.iter().any(|(name,kind)|*name==unit.name&&*kind==unit.kind)&&seen.insert(&unit.name),"backup.invalid_desktop_unit");}ensure!(UNITS.iter().filter(|(name,_)|!["pet-window-state.json","browser-profiles.json","browser-preferences.json","browser-downloads.json","interaction-computer-preferences.json","interaction-results-v1","keyboard-shortcuts-v1.json","workbench-editor-recovery-v1","logging.json"].contains(name)).all(|(name,_)|seen.iter().any(|seen|seen.as_str()==*name)),"backup.missing_desktop_unit");Ok(())}
